 out=D/'dedup-loftr-block-masks-native-audit-20261011.json';assert not out.exists();rp=D/'dedup-loftr-block-masks-native-20261011.json';r=json.loads(rp.read_text());assert r['status']=='complete_bounded_native_joint_recovery_collection_controls' and len(r['results'])==1;assert all(sha(p)==h for p,h in r['pins'].items());mp=Path(r['source_manifest']);m=json.loads(mp.read_text());S=Path(m['snapshot']);parent=json.loads(Path(m['parent_manifest']).read_text());assert sha(m['parent_manifest'])==m['parent_sha256'];assert all(sha(S/f)==h for f,h in m['file_hashes'].items());assert all(sha(Path(parent['snapshot'])/f)==h for f,h in parent['file_hashes'].items());changes=[f for f,h in m['file_hashes'].items() if parent['file_hashes'].get(f)!=h];assert sorted(changes)==['vendor/loftr/src/coarse_matching.rs','vendor/loftr/src/coarse_matching/tests.rs'];ap=D/'dedup-joint-recovery-native-prefix-0001-audit-20261011.json';a=json.loads(ap.read_text());assert all(sha(p)==h for p,h in a['pins'].items());capture=next(Path(p) for p in a['pins'] if p.endswith('/dedup-joint-recovery-native-prefix-0001-20261011.json'));old=json.loads(capture.read_text());assert r['plan'][0]==old['plan'][0];row=r['results'][0];reference=old['results'][0];assert row['returncode']==0 and row['status']=='passed_bounded_control';assert sha(row['log'])==row['log_sha256'];assert Path(row['log']).read_text()==row['stdout']+row['stderr'];value=json.loads(row['stdout']);assert value==json.loads(reference['stdout']);assert value['managed_used']==0;pixels=value['pairs'][0]['evidence']['pixels'];assert pixels['supported'] and min(pixels['anchors'])>=10
